package com.personalassistant.companion;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.security.MessageDigest;
import java.time.*;
import java.util.*;
import java.util.function.Consumer;

/**
 * Private progress photos: originals in the owner's cloud, comparison shots kept apart from flexed ones by state, and the coach only
 * sees photos the owner approves for that one question.
 */
final class WorkoutPhotos {
    final WorkoutScreen screen;final MainActivity a;final AppUi ui;final WorkoutViews.Sheet sheet;final HashSet<String> selected=new HashSet<>();LinearLayout grid;Button ask;String state="relaxed";
    WorkoutPhotos(WorkoutScreen s,WorkoutViews.Sheet sheet){screen=s;a=s.a;ui=s.ui;this.sheet=sheet;}

    static byte[] read(Context c,Uri uri,int limit)throws IOException{try(InputStream in=c.getContentResolver().openInputStream(uri)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>limit)throw new IOException("Too large");}return out.toByteArray();}}

    void fill(){LinearLayout c=WorkoutViews.card(ui);c.addView(ui.type("Photos",15,20,700,0,ui.text));LinearLayout tabs=ui.row();for(String[] t:new String[][]{{"relaxed","Relaxed"},{"flexed","Flexed"},{"pumped","Pumped"}}){TextView v=ui.type(t[1],13,18,600,0,state.equals(t[0])?ui.accent:ui.muted);v.setPadding(ui.dp(4),ui.dp(10),ui.dp(16),ui.dp(10));v.setOnClickListener(x->{state=t[0];selected.clear();sheetRefresh();});tabs.addView(v);}c.addView(tabs);grid=ui.column();c.addView(grid);ask=ui.quietButton("Choose photos to ask about",this::ask);c.addView(ask,MainParts.params(ui,-1,-2,0,8,0,6));c.addView(ui.quietButton("Add photo",()->add()),WorkoutViews.gap(ui,6));c.addView(ui.type("Each look by your coach needs your approval. Any estimate is a rough range.",12,16,400,0,ui.muted));sheet.body.addView(c,WorkoutViews.gap(ui,10));JSONArray est=estimates();for(int i=est.length()-1;i>=Math.max(0,est.length()-3);i--){JSONObject e=est.optJSONObject(i);sheet.body.addView(ui.type("Rough visual estimate "+WorkoutViews.kg(e.optDouble("low_percent"))+"–"+WorkoutViews.kg(e.optDouble("high_percent"))+"% · "+e.optString("assessed_at").substring(0,10)+". Not a measurement.",12.5f,17,400,0,ui.muted),WorkoutViews.gap(ui,4));}paint();}
    private void sheetRefresh(){View card=(View)grid.getParent();int at=sheet.body.indexOfChild(card);sheet.body.removeViewAt(at);while(sheet.body.getChildCount()>at)sheet.body.removeViewAt(at);fill();}
    private JSONArray estimates(){JSONArray out=new JSONArray();List<JSONObject> r=WorkoutStore.rows(a,"composition");Collections.sort(r,(x,y)->x.optJSONObject("data").optString("assessed_at").compareTo(y.optJSONObject("data").optString("assessed_at")));for(JSONObject x:r)out.put(x.optJSONObject("data"));return out;}
    private void paint(){grid.removeAllViews();List<JSONObject> photos=WorkoutStore.rows(a,"photo");Collections.sort(photos,(x,y)->y.optJSONObject("data").optString("captured_at").compareTo(x.optJSONObject("data").optString("captured_at")));LinearLayout row=null;int n=0;for(JSONObject p:photos){JSONObject d=p.optJSONObject("data");if(!state.equals(d.optString("state")))continue;if(n%3==0){row=ui.row();grid.addView(row,MainParts.params(ui,-1,ui.dp(130),0,0,0,4));}n++;row.addView(tile(p),MainParts.weighted(ui,1,0,0,4,0));row.getChildAt(row.getChildCount()-1).setLayoutParams(new LinearLayout.LayoutParams(0,-1,1));}if(n==0)grid.addView(ui.type("None yet. Morning light, unpumped, same spot each time works best.",13,18,400,0,ui.muted));if(row!=null)for(int i=n%3;i%3!=0;i++)row.addView(new View(a),new LinearLayout.LayoutParams(0,-1,1));}
    private View tile(JSONObject p){JSONObject d=p.optJSONObject("data");String id=p.optString("id");FrameLayout f=new FrameLayout(a);f.setPadding(ui.dp(2),ui.dp(2),ui.dp(2),ui.dp(2));ImageView img=new ImageView(a);img.setScaleType(ImageView.ScaleType.CENTER_CROP);img.setBackground(ui.outline(ui.surfaceAlt,10,selected.contains(id)?ui.accent:0,selected.contains(id)?3:0));img.setClipToOutline(true);img.setContentDescription(d.optString("pose")+" photo, "+d.optString("captured_at").substring(0,10));f.addView(img,new FrameLayout.LayoutParams(-1,-1));TextView date=ui.type(d.optString("captured_at").substring(5,10),11,15,600,0,0xFFFFFFFF);date.setShadowLayer(4,0,1,0xCC000000);date.setPadding(ui.dp(6),0,0,ui.dp(4));f.addView(date,new FrameLayout.LayoutParams(-2,-2,Gravity.BOTTOM));load(d.optString("blob_id"),img);f.setOnClickListener(v->{if(selected.contains(id))selected.remove(id);else if(selected.size()<6)selected.add(id);ask.setText(selected.isEmpty()?"Choose photos to ask about":"Ask coach about "+selected.size()+(selected.size()==1?" photo":" photos"));paint();});f.setOnLongClickListener(v->{new AlertDialog.Builder(a).setTitle("Delete this photo?").setMessage("It's removed from your cloud storage too.").setPositiveButton("Delete",(x,i)->{WorkoutStore.delete(a,"photo",id);selected.remove(id);new File(a.getCacheDir(),"workout-photo-"+d.optString("blob_id")).delete();paint();screen.refresh();}).setNegativeButton("Cancel",null).show();return true;});return f;}
    private void load(String blob,ImageView into){File cached=new File(a.getCacheDir(),"workout-photo-"+blob);new Thread(()->{try{byte[] b;if(cached.isFile())b=java.nio.file.Files.readAllBytes(cached.toPath());else{b=Cloud.raw(a,"GET","workout/photos/"+blob,null,null);java.nio.file.Files.write(cached.toPath(),b);}BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=4;Bitmap bmp=BitmapFactory.decodeByteArray(b,0,b.length,o);a.runOnUiThread(()->into.setImageBitmap(bmp));}catch(Exception ignored){}}).start();}
    private void add(){WorkoutPicker.pick(a,"image/*",uri->new AlertDialog.Builder(a).setTitle("Which pose?").setItems(new String[]{"Front","Side","Back"},(x,i)->upload(uri,new String[]{"front","side","back"}[i])).show());}
    private void upload(Uri uri,String pose){Toast.makeText(a,"Saving to your private storage…",Toast.LENGTH_SHORT).show();new Thread(()->{String problem=null;try{byte[] b=read(a,uri,8*1024*1024);String type=a.getContentResolver().getType(uri);if(type==null||!type.matches("image/(jpeg|png|webp)"))throw new IllegalArgumentException("Use a JPEG, PNG or WebP photo.");StringBuilder hex=new StringBuilder();for(byte x:MessageDigest.getInstance("SHA-256").digest(b))hex.append(String.format(Locale.ROOT,"%02x",x));Cloud.raw(a,"PUT","workout/photos/"+hex,b,type);WorkoutStore.put(a,"photo",WorkoutStore.id(),new JSONObject().put("captured_at",OffsetDateTime.now().withNano(0).toString()).put("blob_id",hex.toString()).put("pose",pose).put("state",state));WorkoutStore.sync(a);}catch(IllegalArgumentException e){problem=e.getMessage();}catch(IOException e){problem="Photos must be under 8 MB, and you need a connection to save one.";}catch(Exception e){problem="Couldn't save the photo.";}String m=problem;a.runOnUiThread(()->{if(m!=null)Toast.makeText(a,m,Toast.LENGTH_LONG).show();paint();});}).start();}
    private void ask(){if(selected.isEmpty()){Toast.makeText(a,"Tap the photos you want to ask about",Toast.LENGTH_SHORT).show();return;}int n=selected.size();new AlertDialog.Builder(a).setTitle("Send "+n+(n==1?" photo":" photos")+" to your coach?").setMessage("Only "+(n==1?"this photo":"these photos")+" will be analysed, for this question only.").setPositiveButton("Approve",(x,i)->{JSONArray ids=new JSONArray();for(String id:selected)ids.put(id);selected.clear();screen.coach.open(new JSONObject(),null,"Compare these photos and give a rough range only.",ids);}).setNegativeButton("Cancel",null).show();}
}
